Fetch-data-from-MS-SQL.body:
// Add operations here

sql(`
  SELECT TABLE_NAME 
  FROM INFORMATION_SCHEMA.TABLES 
  WHERE TABLE_TYPE = 'BASE TABLE'
`);


fn(state => {
  const tables = state.data;
  return { ...state, tables, allRecords: {} };
});

each(
  dataPath('tables[*]'),
  sql(state => `SELECT * FROM ${state.data.TABLE_NAME}`, {}, (state, refs) => {
    const tableName = state.data.TABLE_NAME;
    return {
      ...state,
      allRecords: {
        ...state.allRecords,
        [tableName]: refs
      }
    };
  })
);

